source(file.path(dirname(normalizePath(sub("^--file=", "", grep("^--file=", commandArgs(FALSE), value=TRUE)[1]), mustWork=FALSE)), "backend_common.R"))
opts<-parse_cli_args(); require_args(opts,c("vectors","outdir")); v<-readr::read_tsv(opts$vectors,show_col_types=FALSE); cols<-grep("^v",names(v),value=TRUE); M<-as.matrix(v[,cols]); base<-mean(compute_loo_cosines(M),na.rm=TRUE); out<-tibble(subject_id=v$subject_id,deleted_loo_mean=vapply(seq_len(nrow(M)),function(i)mean(compute_loo_cosines(M[-i,,drop=FALSE]),na.rm=TRUE),numeric(1)))%>%mutate(change_from_full=deleted_loo_mean-base);write_tsv_safe(out,file.path(ensure_outdir(opts$outdir),"influence_diagnostics.tsv"))
